create schema if not exists lead_search_internal;
revoke all on schema lead_search_internal from public, anon;
grant usage on schema lead_search_internal to authenticated;
create function lead_search_internal.overture_fallback(p_segment text,p_city text,p_state text)
returns jsonb language plpgsql security definer set search_path='' as $function$
declare
  v_user uuid := auth.uid();
  v_city text;
  v_categories text[];
  v_results jsonb;
begin
  if v_user is null or not exists(select 1 from public.private_access where user_id=v_user) then
    return jsonb_build_object('ok',false,'code','FORBIDDEN','message','Conta não autorizada.');
  end if;
  if p_segment is null or length(p_segment)>120 or p_city is null or length(p_city) not between 2 and 120 or p_state is null or p_state !~ '^[A-Z]{2}$' then
    return jsonb_build_object('ok',false,'code','INVALID_REQUEST','message','Informe nicho, cidade e UF válidos.');
  end if;
  if not public.claim_api_request_for_user(v_user,'places_search') then
    return jsonb_build_object('ok',false,'code','QUOTA','message','Limite temporário de busca atingido.');
  end if;
  v_city := trim(regexp_replace(translate(lower(p_city),'áàâãäéèêëíìîïóòôõöúùûüç','aaaaaeeeeiiiiooooouuuuc'),'[^a-z0-9]+',' ','g'));
  select array_agg(x) into v_categories from jsonb_array_elements_text(coalesce(($mapping${"Açougue":["butcher_shop"],"Cafeteria":["coffee_shop","cafe"],"Confeitaria":["bakery","dessert_shop","chocolatier"],"Doceria":["dessert_shop","candy_store"],"Hamburgueria":["hamburger_restaurant","burger_restaurant"],"Hortifruti":["fruit_and_vegetable_store","greengrocer","produce_store"],"Padaria":["bakery"],"Peixaria":["seafood_market","fishmonger"],"Pizzaria":["pizza_restaurant"],"Restaurante":["restaurant","brazilian_restaurant","barbecue_restaurant","steakhouse","italian_restaurant","seafood_restaurant","bar_and_grill_restaurant","diner","buffet_restaurant"],"Sorveteria":["ice_cream_shop"],"Barbearia":["barber"],"Salão de Beleza":["beauty_salon","hair_salon"],"Estúdio de Tatuagem":["tattoo_shop","tattoo_and_piercing"],"Spa":["spa"],"Manicure":["nail_salon"],"Clínica Odontológica":["dental_clinic","dentist","general_dentistry","orthodontics","cosmetic_dentistry"],"Clínica Médica":["medical_clinic","doctors_office","outpatient_care_facility"],"Farmácia":["pharmacy"],"Fisioterapeuta":["physical_therapy_clinic","physiotherapist","physical_therapy"],"Ótica":["optician","optical_store","eyewear_store"],"Psicólogo / Terapeuta":["psychologist","psychotherapy","psychology"],"Chaveiro":["locksmith","key_and_locksmith"],"Eletricista":["electrician"],"Lavanderia":["laundry","dry_cleaner","laundromat","dry_cleaning"],"Marcenaria":["carpenter"],"Serralheria":["metal_workshop","metal_fabricator"],"Arquiteto / Escritório de Arquitetura":["architect","architectural_designer"],"Construtora":["construction_company"],"Loja de Tintas":["paint_store"],"Estacionamento":["parking"],"Estética Automotiva":["car_wash","auto_detailing"],"Lava-Rápido":["car_wash"],"Locadora de Veículos":["car_rental","car_rental_service"],"Loja de Pneus":["tire_shop","tire_dealer_and_repair"],"Loja de Veículos Seminovos":["car_dealer","used_car_dealer","auto_dealer","used_auto_dealer"],"Mecânica Automotiva":["automotive_repair","auto_repair"],"Oficina de Motos":["motorcycle_repair_shop","motorcycle_repair"],"Academia":["gym","fitness_center"],"Academia de Artes Marciais":["martial_arts_school","martial_arts_club"],"Autoescola":["driving_school"],"Berçário / Creche":["day_care_center","day_care_preschool"],"Escola de Idiomas":["language_school"],"Escola de Música":["music_school"],"Escola Infantil":["preschool"],"Casa de Festas":["event_venue"],"Agência de Viagens":["travel_agency","travel_agent"],"Hostel":["hostel"],"Hotel":["hotel"],"Pousada":["inn","guest_house","bed_and_breakfast"],"Resort":["resort"],"Contabilidade":["accountant"],"Escritório de Advocacia":["attorney_or_law_firm"],"Gráfica Rápida":["printing_service"],"Clínica de Pilates":["pilates_studio"],"Loja de Moda Infantil":["childrens_clothing_store"],"Laboratório de Análises Clínicas":["laboratory_testing"],"Fotógrafo":["photographer","photography_service"],"Coworking":["coworking_space"],"Floricultura":["florist","flowers_and_gifts_store"],"Imobiliária":["real_estate_agency","real_estate_service","real_estate_agent"],"Joalheria":["jewelry_store"],"Loja de Bicicletas":["bicycle_store","bike_store"],"Loja de Calçados":["shoe_store"],"Loja de Informática":["computer_store"],"Loja de Instrumentos Musicais":["musical_instrument_store"],"Loja de Materiais de Construção":["building_materials_store","building_supply_store","hardware_store","lumber_store"],"Loja de Móveis":["furniture_store"],"Loja de Presentes":["gift_shop"],"Loja de Roupas":["clothing_store","womens_clothing_store","mens_clothing_store","fashion_boutique"],"Papelaria / Artesanato":["stationery_store","office_supply_store","arts_crafts_and_hobby_store"],"Clínica Veterinária":["veterinary_care","veterinarian"],"Pet Shop":["pet_store"],"Loja Agropecuária":["agricultural_supply_store","agricultural_seed_store"],"Transportadora":["trucking_company","transportation_service","freight_and_cargo_service"],"Agência de Turismo Receptivo":["tour_operator"],"Aluguel de Temporada":["holiday_rental_home"],"Assistência Técnica de Celular":["mobile_phone_repair"],"Bar / Pub":["bar","pub","beer_bar","cocktail_bar","gastropub","wine_bar","beer_garden"],"Mercado / Supermercado":["grocery_store"],"Restaurante Japonês":["sushi_restaurant","japanese_restaurant"],"Provedor de Internet":["internet_service_provider"],"Autopeças":["auto_parts_store"],"Posto de Combustível":["gas_station","fueling_station"],"Revenda de Motos":["motorcycle_dealer"],"Funerária":["funeral_service"],"Livraria":["bookstore"],"Loja de Artigos Esportivos":["sporting_goods_store"],"Loja de Artigos para Festas":["party_supply_store"],"Loja de Brinquedos":["toy_store"],"Loja de Celulares":["mobile_phone_store"],"Loja de Cosméticos":["beauty_supply_store","hair_supply_store","beauty_product_supplier"],"Loja de Conveniência":["convenience_store"],"Loja de Departamentos":["department_store"],"Loja de Eletrônicos":["electronics_store"],"Loja de Eletrodomésticos":["appliance_store"],"Loja de Lingerie":["lingerie_store"],"Loja de Utilidades Domésticas":["home_goods_store"],"Banho e Tosa":["pet_groomer"],"Loja de Suplementos":["vitamin_and_supplement_store"],"Vidraçaria":["glass_and_mirror_sales_service"],"Energia Solar":["solar_installation"],"Escola de Dança":["dance_studio"],"Corretor de Seguros":["insurance_agency"],"Marketing Digital":["marketing_agency","internet_marketing_service","social_media_agency"],"Marmoraria":["granite_supplier"],"Loja de Produtos Naturais":["health_food_store"],"Desenvolvimento de Software":["software_development"],"Empresa de Uniformes":["uniform_store"],"Funilaria":["auto_body_shop"],"Refrigeração / Ar Condicionado":["hvac_service"],"Piscineiro":["pool_cleaning"],"Personal Trainer":["fitness_trainer"],"Fotografia de Eventos":["event_photography_service"],"Agência de Publicidade":["advertising_agency","b2b_advertising_and_marketing_service"],"Costureira / Ateliê":["sewing_and_alterations"],"Nutricionista":["nutrition_service"],"Dermatologista":["dermatology"],"Clínica de Estética":["medical_spa"],"Loja de Colchões":["mattress_store"],"Empresa de Limpeza Residencial":["home_cleaning"],"Segurança Eletrônica / Alarmes":["home_security"],"Empório":["specialty_foods_store"],"Acessórios Automotivos":["car_stereo_store"],"Escola de Informática":["computer_coaching"],"Acupuntura":["acupuncture"],"Adega":["liquor_store"],"Adestramento":["dog_trainer"],"Assessoria de Casamentos":["wedding_planning"],"Auto Elétrica":["auto_electrical_repair"],"Bronzeamento":["tanning_salon"],"Cardiologista":["cardiology"],"Cartório / Serviços Notariais":["notary_public"],"Clínica de Imagem":["radiology"],"Consultoria Empresarial":["business_consulting"],"Consultoria Financeira":["financial_advising"],"Curso Profissionalizante":["vocational_and_technical_school"],"Dedetizadora":["pest_control_service"],"Depilação a Laser":["laser_hair_removal"],"DJ / Som para Eventos":["dj_service"],"Empresa de Recrutamento":["employment_agency"],"Encanador":["plumbing"],"Estética / Depilação":["hair_removal","waxing"],"Fonoaudiólogo":["speech_therapy"],"Ginecologista":["obstetrics_and_gynecology"],"Guincho":["towing_service"],"Home Care / Cuidados Domiciliares":["home_health_care"],"Hotel para Pets":["pet_boarding"],"Jardinagem / Paisagismo":["landscaping","gardener"],"Loja de Iluminação":["lighting_store"],"Loja de Rações":["livestock_feed_and_supply_store"],"Maquiagem Profissional":["makeup_artist"],"Massoterapeuta":["massage_therapy"],"Medicina e Segurança do Trabalho":["occupational_safety","occupational_medicine"],"Montador de Móveis":["furniture_assembly"],"Ortopedista":["orthopedics"],"Passeios Turísticos":["sightseeing_tour_agency","boat_tour","bus_tour"],"Pediatra":["pediatric_clinic"],"Pet Sitter":["pet_sitting"],"Podólogo":["podiatry"],"Psiquiatra":["psychiatry"],"Reforço Escolar":["tutoring_service"],"Terapeuta Ocupacional":["occupational_therapy"],"Vistoria Veicular":["emissions_inspection"]}$mapping$::jsonb)->p_segment,'[]'::jsonb)) x;
  select coalesce(jsonb_agg(jsonb_build_object(
    'placeId','overture:'||q.id,'source','overture','sourceUrl','https://explore.overturemaps.org/',
    'name',q.name,'primaryCategory',q.category,'categories',jsonb_build_array(q.category),
    'description',null,'address',q.address,'neighborhood',null,'city',q.city,'state',q.state,
    'phone',q.phone,'email',q.email,'internationalPhone',null,'rating',null,'reviewCount',null,
    'isOpenNow',null,'openingHours','[]'::jsonb,'website',q.website,'instagram',null,
    'googleMapsUrl',null,'businessStatus',q.operating_status,'latitude',q.latitude,'longitude',q.longitude
  ) order by q.score desc,q.id),'[]'::jsonb) into v_results
  from (
    select o.*, (case when length(regexp_replace(coalesce(o.phone,''),'[^0-9]','','g')) between 10 and 13 then 12 else 0 end +
    case when nullif(trim(o.email),'') is not null then 7 else 0 end +
    case when nullif(trim(o.website),'') is not null then 5 else 0 end + coalesce(o.confidence,0)*4) score
    from public.overture_places o
    where o.state=p_state and o.city_key=v_city and o.category=any(v_categories)
    and o.operating_status is distinct from 'permanently_closed' and nullif(trim(o.name),'') is not null
    order by score desc,o.id limit 20
  ) q;
  return jsonb_build_object('ok',true,'results',v_results,'nextPageToken',null,'provider','overture');
end;
$function$;
revoke all on function lead_search_internal.overture_fallback(text,text,text) from public,anon,authenticated;
grant execute on function lead_search_internal.overture_fallback(text,text,text) to authenticated;
create function public.search_overture_fallback(p_segment text,p_city text,p_state text)
returns jsonb language sql security invoker set search_path='' as $function$
  select lead_search_internal.overture_fallback(p_segment,p_city,p_state);
$function$;
revoke all on function public.search_overture_fallback(text,text,text) from public,anon,authenticated;
grant execute on function public.search_overture_fallback(text,text,text) to authenticated;
notify pgrst, 'reload schema';